blogger_theme_designer_bridge.mapeamento_css:
:root {
  --bulma-primary: $(theme.color.primary);
  --bulma-text: $(theme.color.text);
  --bulma-footer: $(theme.color.footer);
  --bulma-bg: #F5F7F8;
}
body { background: $(body.background); color: var(--bulma-text); font: $(body.font); }
h1, h2, h3 { font: $(heading.font); }
